from __future__ import annotations

from decimal import Decimal

from app.ict.base import BarData, BaseDetector
from app.ict.detectors.swing import SwingDetector
from app.models.enums import BiasType, MarketEventType


class LiquiditySweepDetector(BaseDetector):
    def __init__(self, tolerance_ticks: int = 2, tick_size: Decimal = Decimal("0.25"), swing_n: int = 3) -> None:
        self.tolerance = Decimal(tolerance_ticks) * tick_size
        self._swing = SwingDetector(n=swing_n)

    def detect(self, bars: list[BarData]) -> list[dict]:
        swing_results = self._swing.detect_with_index(bars)

        swing_highs: list[tuple[Decimal, int]] = []
        swing_lows: list[tuple[Decimal, int]] = []
        for event, bar_idx in swing_results:
            if event["event_type"] == MarketEventType.swing_high:
                swing_highs.append((event["price_high"], bar_idx))
            else:
                swing_lows.append((event["price_low"], bar_idx))

        events = []

        for i, bar in enumerate(bars):
            bsl_clusters = _find_clusters(swing_highs, self.tolerance, before_idx=i)
            for cluster_price, count in bsl_clusters:
                if bar.high > cluster_price and bar.close < cluster_price:
                    events.append({
                        "instrument": bar.instrument,
                        "timeframe": bar.timeframe,
                        "event_type": MarketEventType.sweep,
                        "timestamp": bar.timestamp,
                        "direction": BiasType.bullish,
                        "price_high": bar.high,
                        "price_low": cluster_price,
                        "price_midpoint": (bar.high + cluster_price) / Decimal("2"),
                        "confidence": None,
                        "metadata": {
                            "liquidity_type": "bsl",
                            "equal_level": float(cluster_price),
                            "num_equal_points": count,
                        },
                    })

            ssl_clusters = _find_clusters(swing_lows, self.tolerance, before_idx=i)
            for cluster_price, count in ssl_clusters:
                if bar.low < cluster_price and bar.close > cluster_price:
                    events.append({
                        "instrument": bar.instrument,
                        "timeframe": bar.timeframe,
                        "event_type": MarketEventType.sweep,
                        "timestamp": bar.timestamp,
                        "direction": BiasType.bearish,
                        "price_high": cluster_price,
                        "price_low": bar.low,
                        "price_midpoint": (cluster_price + bar.low) / Decimal("2"),
                        "confidence": None,
                        "metadata": {
                            "liquidity_type": "ssl",
                            "equal_level": float(cluster_price),
                            "num_equal_points": count,
                        },
                    })

        return events


def _find_clusters(
    levels: list[tuple[Decimal, int]],
    tolerance: Decimal,
    before_idx: int,
) -> list[tuple[Decimal, int]]:
    eligible = [price for price, idx in levels if idx < before_idx]
    if len(eligible) < 2:
        return []

    clusters: list[tuple[Decimal, int]] = []
    used = [False] * len(eligible)

    for i, base in enumerate(eligible):
        if used[i]:
            continue
        group = [base]
        for j in range(i + 1, len(eligible)):
            if not used[j] and abs(eligible[j] - base) <= tolerance:
                group.append(eligible[j])
                used[j] = True
        if len(group) >= 2:
            avg = sum(group) / len(group)
            clusters.append((avg, len(group)))
        used[i] = True

    return clusters

