from app.ict.base import BarData, BaseDetector
from app.ict.detectors.swing import SwingDetector
from app.models.enums import BiasType, MarketEventType


class MarketStructureDetector(BaseDetector):
    def __init__(self, swing_n: int = 3) -> None:
        self._swing = SwingDetector(n=swing_n)

    def detect(self, bars: list[BarData]) -> list[dict]:
        swing_results = self._swing.detect_with_index(bars)

        swing_highs: list[tuple[Decimal, int]] = []
        swing_lows: list[tuple[Decimal, int]] = []
        for event, bar_idx in swing_results:
            if event["event_type"] == MarketEventType.swing_high:
                swing_highs.append((event["price_high"], bar_idx, event["timestamp"]))
            else:
                swing_lows.append((event["price_low"], bar_idx, event["timestamp"]))

        events = []
        trend: str = "unknown"
        last_broken_high_idx: int = -1
        last_broken_low_idx: int = -1

        for i, bar in enumerate(bars):
            available_highs = [(p, idx, ts) for p, idx, ts in swing_highs if idx < i]
            available_lows = [(p, idx, ts) for p, idx, ts in swing_lows if idx < i]

            if not available_highs and not available_lows:
                continue

            if available_highs:
                last_high_price, last_high_idx, last_high_ts = available_highs[-1]
                second_last_high = available_highs[-2] if len(available_highs) >= 2 else None

                if bar.close > last_high_price and last_high_idx > last_broken_high_idx:
                    last_broken_high_idx = last_high_idx
                    if trend == "bullish":
                        event_type = MarketEventType.bos
                    elif trend == "bearish":
                        event_type = MarketEventType.choch
                    elif second_last_high and bar.close > second_last_high[0]:
                        event_type = MarketEventType.mss
                    else:
                        event_type = MarketEventType.choch

                    trend_before = trend
                    trend = "bullish"
                    events.append({
                        "instrument": bar.instrument,
                        "timeframe": bar.timeframe,
                        "event_type": event_type,
                        "timestamp": bar.timestamp,
                        "direction": BiasType.bullish,
                        "price_high": last_high_price,
                        "price_low": last_high_price,
                        "price_midpoint": last_high_price,
                        "confidence": None,
                        "metadata": {
                            "broken_swing_ts": last_high_ts.isoformat(),
                            "swing_price": float(last_high_price),
                            "trend_before": trend_before,
                        },
                    })

            if available_lows:
                last_low_price, last_low_idx, last_low_ts = available_lows[-1]
                second_last_low = available_lows[-2] if len(available_lows) >= 2 else None

                if bar.close < last_low_price and last_low_idx > last_broken_low_idx:
                    last_broken_low_idx = last_low_idx
                    if trend == "bearish":
                        event_type = MarketEventType.bos
                    elif trend == "bullish":
                        event_type = MarketEventType.choch
                    elif second_last_low and bar.close < second_last_low[0]:
                        event_type = MarketEventType.mss
                    else:
                        event_type = MarketEventType.choch

                    trend_before = trend
                    trend = "bearish"
                    events.append({
                        "instrument": bar.instrument,
                        "timeframe": bar.timeframe,
                        "event_type": event_type,
                        "timestamp": bar.timestamp,
                        "direction": BiasType.bearish,
                        "price_high": last_low_price,
                        "price_low": last_low_price,
                        "price_midpoint": last_low_price,
                        "confidence": None,
                        "metadata": {
                            "broken_swing_ts": last_low_ts.isoformat(),
                            "swing_price": float(last_low_price),
                            "trend_before": trend_before,
                        },
                    })

        return events

