from app.ict.base import BarData, BaseDetector
from app.ict.detectors.swing import SwingDetector
from app.models.enums import MarketEventType


class MarketStructureDetector(BaseDetector):
    """BOS, CHoCH, and MSS detection using confirmed swing points.

    - BOS: price closes beyond a prior swing high/low in the direction of current trend
    - CHoCH: price closes beyond a swing level against current trend
    - MSS: price closes beyond the second-to-last swing level against current trend
      (more significant structural shift than CHoCH)

    Trend is inferred from the most recent BOS direction.
    """

    def __init__(self, swing_n: int = 3) -> None:
        self._swing = SwingDetector(n=swing_n)

    def detect(self, bars: list[BarData]) -> list[dict]:
        swing_events_with_idx = self._swing.detect_with_index(bars)

        swing_highs: list[tuple[float, int]] = []
        swing_lows: list[tuple[float, int]] = []
        for ev, idx in swing_events_with_idx:
            if ev["event_type"] == MarketEventType.swing_high:
                swing_highs.append((ev["price_high"], idx))
            else:
                swing_lows.append((ev["price_low"], idx))

        events: list[dict] = []
        trend: str = "unknown"

        for i in range(1, len(bars)):
            bar = bars[i]
            close = float(bar.close)

            # Filter swing points confirmed before bar i
            prior_highs = [(p, idx) for p, idx in swing_highs if idx < i]
            prior_lows = [(p, idx) for p, idx in swing_lows if idx < i]

            if not prior_highs and not prior_lows:
                continue

            # Check bullish break (close above a prior swing high)
            if prior_highs:
                last_high, last_high_idx = prior_highs[-1]
                if close > last_high:
                    broken_bar = bars[last_high_idx]
                    if trend == "bullish":
                        ev_type = MarketEventType.bos
                    elif trend in ("bearish", "unknown"):
                        ev_type = MarketEventType.choch
                        if trend == "bearish" and len(prior_highs) >= 2:
                            second_high, _ = prior_highs[-2]
                            if close > second_high:
                                ev_type = MarketEventType.mss
                    else:
                        ev_type = MarketEventType.bos

                    trend = "bullish"
                    events.append({
                        "instrument": bar.instrument,
                        "timeframe": bar.timeframe,
                        "event_type": ev_type,
                        "timestamp": bar.timestamp,
                        "direction": "bullish",
                        "price_high": last_high,
                        "price_low": last_high,
                        "price_midpoint": last_high,
                        "confidence": None,
                        "metadata": {
                            "broken_swing_ts": broken_bar.timestamp.isoformat(),
                            "swing_price": last_high,
                            "trend_before": trend if trend != "bullish" else "bullish",
                        },
                    })

            # Check bearish break (close below a prior swing low)
            if prior_lows:
                last_low, last_low_idx = prior_lows[-1]
                if close < last_low:
                    broken_bar = bars[last_low_idx]
                    if trend == "bearish":
                        ev_type = MarketEventType.bos
                    elif trend in ("bullish", "unknown"):
                        ev_type = MarketEventType.choch
                        if trend == "bullish" and len(prior_lows) >= 2:
                            second_low, _ = prior_lows[-2]
                            if close < second_low:
                                ev_type = MarketEventType.mss
                    else:
                        ev_type = MarketEventType.bos

                    trend = "bearish"
                    events.append({
                        "instrument": bar.instrument,
                        "timeframe": bar.timeframe,
                        "event_type": ev_type,
                        "timestamp": bar.timestamp,
                        "direction": "bearish",
                        "price_high": last_low,
                        "price_low": last_low,
                        "price_midpoint": last_low,
                        "confidence": None,
                        "metadata": {
                            "broken_swing_ts": broken_bar.timestamp.isoformat(),
                            "swing_price": last_low,
                            "trend_before": trend if trend != "bearish" else "bearish",
                        },
                    })

        return events

